{"path":"pricing.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Investments — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fff8f2;--panel:#fff;--muted:#7b5a44;--accent:#8b5e3c;--accent-2:#c08a5a;--glass:rgba(255,255,255,0.6)}
    *{box-sizing:border-box}
    html,body{height:100%}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;line-height:1.45;color:var(--muted);background:var(--bg) url('/assets/img/pattern.svg') repeat;}
    header{background:linear-gradient(180deg,rgba(139,94,60,0.06),transparent);padding:28px 20px;border-bottom:1px solid rgba(139,94,60,0.06)}
    .wrap{max-width:920px;margin:0 auto}
    nav{display:flex;gap:14px;align-items:center;flex-wrap:wrap}
    nav a{color:var(--muted);text-decoration:none;padding:6px 8px;border-radius:6px;font-weight:600}
    nav a.current{background:var(--accent-2);color:white}
    .hero{padding:48px 0 20px}
    .hero h1{margin:6px 0 12px;color:#462b1b;font-size:30px}
    .hero p{margin:0 0 18px;max-width:60ch}
    .cta-row{display:flex;gap:12px;flex-wrap:wrap}
    .btn{background:var(--accent);color:white;padding:10px 14px;border-radius:8px;text-decoration:none;font-weight:700}
    .btn.ghost{background:transparent;border:2px solid var(--accent);color:var(--accent)}
    main{padding:28px 20px}
    .tiers{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:18px}
    .tier{background:var(--panel);padding:18px;border-radius:12px;box-shadow:0 6px 18px rgba(15,10,8,0.04);border:1px solid rgba(139,94,60,0.06)}
    .tier h3{margin:0 0 8px;color:#3b2315}
    .price{font-size:20px;color:var(--accent);font-weight:800;margin:8px 0}
    ul{padding-left:18px;margin:8px 0}
    .note{font-size:13px;color:#6b4f3d}
    footer{padding:28px 20px;border-top:1px dashed rgba(139,94,60,0.06);text-align:center;color:#6b4f3d}
    .reveal{opacity:0;transform:translateY(12px);transition:opacity .6s ease,transform .6s ease}
    .reveal.revealed{opacity:1;transform:none}
    /* small planner teaser */
    .planner-tease{margin-top:16px;padding:12px;background:linear-gradient(180deg,var(--glass),transparent);border-radius:10px;border:1px solid rgba(139,94,60,0.06)}
    .planner-tease label{font-size:13px;color:#5b4334}
    .planner-tease input, .planner-tease select{width:100%;padding:8px;border-radius:8px;border:1px solid rgba(99,69,50,0.08);margin-top:6px}
    .planner-actions{display:flex;gap:8px;margin-top:10px}
    @media(min-width:720px){.hero h1{font-size:38px}}
  </style>
</head>
<body>
  <header>
    <div class="wrap">
      <nav aria-label="primary navigation">
        <a href="index.html">Home</a>
        <a href="about.html">Roots</a>
        <a href="services.html">Offerings</a>
        <a href="programs.html">Rhythms</a>
        <a href="pricing.html" class="current">Investments</a>
        <a href="testimonials.html">Stories</a>
        <a href="book.html">Begin</a>
        <a href="contact.html">Reach</a>
      </nav>
    </div>
  </header>

  <main class="wrap">
    <section class="hero reveal" id="overview">
      <h1>Choose the right container for the change you want</h1>
      <p>Each path is shaped around behaviors, routines, and simple frameworks to scaffold your energy, attention, and rest. No quick fixes — clear structures you can keep.</p>
      <div class="cta-row">
        <a class="btn" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        <a class="btn ghost" href="book.html">Plan a free intro</a>
      </div>
    </section>

    <section class="reveal" id="tiers" style="margin-top:22px">
      <div class="tiers">
        <article class="tier">
          <h3>Deep Root Intensive</h3>
          <div class="price">$2,400 — one-time</div>
          <p class="note">For a focused reset over 8–12 weeks. Includes tools, weekly coaching and a tailored habit scaffold.</p>
          <ul>
            <li>Personal baseline, weekly sessions, written action plans</li>
            <li>Three core habits with stepwise progressions</li>
            <li>Framework for making decisions that conserve energy</li>
          </ul>
          <div class="note">Best for when a sustained change requires a structure to live in.</div>
        </article>

        <article class="tier">
          <h3>Seasonal Reset</h3>
          <div class="price">$850 — seasonal (12 weeks)</div>
          <p class="note">An energetic recalibration tied to a quarter: pick a clear focus and practical checkpoints.</p>
          <ul>
            <li>Biweekly coaching calls</li>
            <li>A compact daily routine and check-in template</li>
            <li>Email prompts and mid-course adjustments</li>
          </ul>
        </article>

        <article class="tier">
          <h3>Compass Sessions</h3>
          <div class="price">$280 — monthly subscription</div>
          <p class="note">Short, targeted coaching to keep momentum. Flexible and simple checkpoints each month.</p>
          <ul>
            <li>Monthly planning session + resource packet</li>
            <li>Habit micro-commitments for steady progress</li>
            <li>Tools to repurpose each month across focuses</li>
          </ul>
        </article>
      </div>
    </section>

    <section class="reveal" id="planner" style="margin-top:22px">
      <h2>Quick Session Planner</h2>
      <p class="note">Draft a short plan and move forward from there — this teaser gives an instant outline you can refine when you book.</p>
      <div class="planner-tease">
        <label for="pt-focus">Primary focus</label>
        <select id="pt-focus">
          <option>Energy rhythm</option>
          <option>Boundaries & rhythm</option>
          <option>Daily habit architecture</option>
          <option>Sleep & wind-down scaffolding</option>
        </select>
        <label for="pt-duration">Preferred duration (weeks)</label>
        <input id="pt-duration" type="number" min="2" max="24" value="8">
        <div class="planner-actions">
          <button class="btn" id="pt-build">Build outline</button>
          <a class="btn ghost" href="book.html">Open full planner</a>
        </div>
        <pre id="pt-output" style="margin-top:8px;background:#fff;padding:10px;border-radius:8px;white-space:pre-wrap;font-size:13px;color:#6b4f3d"></pre>
      </div>
    </section>

  </main>

  <footer>
    <div class="wrap">
      <small>Questions? Call {{PHONE}} or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></small>
    </div>
  </footer>

  <script>
    // Scroll reveal with reduced-motion support
    (function(){
      const prefersReduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const items = document.querySelectorAll('.reveal');
      if(prefersReduce){ items.forEach(i=>i.classList.add('revealed')); return; }
      const obs = new IntersectionObserver(entries=>{
        entries.forEach(e=>{ if(e.isIntersecting){ e.target.classList.add('revealed'); obs.unobserve(e.target); } });
      },{threshold:0.12});
      items.forEach(i=>obs.observe(i));
    })();

    // Quick planner teaser logic
    document.getElementById('pt-build').addEventListener('click', function(){
      const focus = document.getElementById('pt-focus').value;
      const dur = parseInt(document.getElementById('pt-duration').value,10) || 8;
      const weeks = Math.max(2, Math.min(24, dur));
      const sessions = Math.ceil(weeks/2);
      const habits = focus.includes('habit') ? ['Micro habit A','Micro habit B'] : ['Daily anchor','Evening check-in'];
      const text = `Focus: ${focus}\nDuration: ${weeks} weeks\nPlanned sessions: ${sessions} (biweekly rhythm)\nCore habits:\n - ${habits.join('\n - ')}\nCheckpoints: Week 4, Week ${Math.min(weeks,8)}`;
      document.getElementById('pt-output').textContent = text;
    });
  </script>
</body>
</html>"} 
