{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Book — Plan a session</title>
  <style>
    :root{--bg:#fff8f2;--card:#fff;--accent:#8b5e3c;--muted:#6b4f3d}
    *{box-sizing:border-box}
    body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,'Helvetica Neue',Arial;color:var(--muted);background:var(--bg) url('/assets/img/pattern.svg') repeat}
    .wrap{max-width:920px;margin:0 auto;padding:22px}
    nav{display:flex;gap:12px;flex-wrap:wrap}
    nav a{color:var(--muted);text-decoration:none;padding:6px 8px;border-radius:6px;font-weight:600}
    header{padding-bottom:8px}
    h1{color:#3b2315}
    .grid{display:grid;grid-template-columns:1fr;gap:18px}
    @media(min-width:880px){.grid{grid-template-columns:1fr 360px}}
    .card{background:var(--card);padding:16px;border-radius:12px;border:1px solid rgba(139,94,60,0.06);box-shadow:0 8px 22px rgba(12,8,6,0.04)}
    label{display:block;margin-top:10px;font-weight:700;color:#4a3224}
    input[type=text], input[type=email], select, textarea, input[type=number]{width:100%;padding:10px;border-radius:8px;border:1px solid rgba(99,69,50,0.08);margin-top:6px}
    textarea{min-height:110px}
    .btn{display:inline-block;background:var(--accent);color:white;padding:10px 14px;border-radius:9px;text-decoration:none;border:none;font-weight:700}
    .secondary{background:transparent;border:2px solid var(--accent);color:var(--accent)}
    .output{white-space:pre-wrap;background:#fff;padding:12px;border-radius:10px;border:1px solid rgba(139,94,60,0.06);margin-top:12px;color:#5b4133}
    .reveal{opacity:0;transform:translateY(12px);transition:opacity .6s ease,transform .6s ease}
    .reveal.revealed{opacity:1;transform:none}
    .small{font-size:13px;color:#7b5a44}
  </style>\head>
<body>
  <div class="wrap">
    <header>
      <nav aria-label="primary navigation">
        <a href="index.html">Home</a>
        <a href="about.html">Roots</a>
        <a href="services.html">Offerings</a>
        <a href="programs.html">Rhythms</a>
        <a href="pricing.html">Investments</a>
        <a href="testimonials.html">Stories</a>
        <a href="book.html" aria-current="page">Begin</a>
        <a href="contact.html">Reach</a>
      </nav>
    </header>

    <main class="grid">
      <section class="card reveal">
        <h1>Build your Session Plan</h1>
        <p class="small">Create a clear outline that you can copy into an email or keep as a working plan. The plan focuses on outcomes, habits, and a lightweight framework — no medical advice.</p>

        <form id="planner">
          <label for="name">Your name</label>
          <input id="name" type="text" placeholder="First name or full name">

          <label for="email">Email</label>
          <input id="email" type="email" placeholder="you@example.com">

          <label for="goal">Primary goal</label>
          <textarea id="goal" placeholder="Describe the one thing you'd like to change or clarify"></textarea>

          <label for="duration">Duration (weeks)</label>
          <input id="duration" type="number" min="2" max="52" value="8">

          <label for="freq">Sessions per week</label>
          <select id="freq">
            <option value="0.25">Check-in (monthly)</option>
            <option value="0.5">Biweekly</option>
            <option value="1" selected>Weekly</option>
            <option value="2">Twice weekly</option>
          </select>

          <label>Focus areas (pick up to 3)</label>
          <div style="display:flex;gap:8px;flex-wrap:wrap">
            <label><input type="checkbox" value="Sleep" class="focus"> Sleep</label>
            <label><input type="checkbox" value="Boundaries" class="focus"> Boundaries</label>
            <label><input type="checkbox" value="Daily Habits" class="focus"> Daily Habits</label>
            <label><input type="checkbox" value="Energy Rhythm" class="focus"> Energy Rhythm</label>
            <label><input type="checkbox" value="Decision Load" class="focus"> Decision Load</label>
          </div>

          <label for="format">Preferred format</label>
          <select id="format">
            <option>Video</option>
            <option>Phone</option>
            <option>In person</option>
            <option>Async notes + email</option>
          </select>

          <label for="intensity">Intensity — how focused do you want the plan to be?</label>
          <input id="intensity" type="range" min="1" max="10" value="6">

          <div style="margin-top:12px;display:flex;gap:8px;flex-wrap:wrap">
            <button type="button" class="btn" id="build">Create plan</button>
            <button type="button" class="btn secondary" id="clear">Clear</button>
          </div>
        </form>

        <div id="resultArea" style="margin-top:12px">
          <div class="output" id="planText" aria-live="polite">Your plan will appear here.</div>
          <div style="margin-top:10px;display:flex;gap:8px">
            <button class="btn" id="copyBtn">Copy summary</button>
            <button class="btn secondary" id="downloadBtn">Download .txt</button>
            <a class="btn" id="bookNow" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          </div>
        </div>
      </section>

      <aside class="card reveal">
        <h2>How this planner works</h2>
        <p class="small">The widget turns your inputs into a readable session plan with: a short outcome statement, rhythm and session cadence, three starter habits, a checkpoint schedule, and a simple resource list. Use it to confirm what you want before scheduling.</p>

        <h3 style="margin-top:14px">Sample components</h3>
        <ul style="color:#5b4133">
          <li>Outcome: "Be consistently available for focused work blocks by mid-project."</li>
          <li>Session cadence: Weekly 45-min coaching + homework</li>
          <li>Starter habits: morning anchor, single decision buffer, evening reset</li>
          <li>Checkpoints: quick reviews at 2, 4, and final week</li>
        </ul>

        <p class="small" style="margin-top:14px">Questions? Call {{PHONE}} or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      </aside>
    </main>

  </div>

  <script>
    // Scroll reveal
    (function(){
      const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const nodes = document.querySelectorAll('.reveal');
      if(reduced){ nodes.forEach(n=>n.classList.add('revealed')); return; }
      const io = new IntersectionObserver((entries)=>{
        entries.forEach(e=>{ if(e.isIntersecting){ e.target.classList.add('revealed'); io.unobserve(e.target); } });
      },{threshold:0.08});
      nodes.forEach(n=>io.observe(n));
    })();

    // Session Planner logic
    function getCheckedFocus(){
      const checks = Array.from(document.querySelectorAll('.focus:checked')).map(i=>i.value);
      return checks.slice(0,3);
    }

    function chooseHabits(focus){
      const pool = {
        'Sleep':['Evening wind-down (30m)','Consistent wake window'],
        'Boundaries':['Single no-meeting block','Protected email hours'],
        'Daily Habits':['Micro morning ritual','End-of-day triage'],
        'Energy Rhythm':['Two peak work blocks','Midday pause with light movement'],
        'Decision Load':['One decision buffer','Automated micro-choices']
      };
      let habits = [];
      focus.forEach(f=>{ if(pool[f]) habits = habits.concat(pool[f].slice(0,2)); });
      if(habits.length < 3) habits = habits.concat(['Daily anchor (5–10 mins)','Weekly tidy-up']);
      return habits.slice(0,3);
    }

    function estimateInvestment(duration, freq){
      // crude mapping: heavier frequency -> higher investment
      const weeks = Math.max(2, Math.min(52, duration));
      const sessionsPerWeek = parseFloat(freq);
      const sessions = Math.max(1, Math.round(weeks * sessionsPerWeek));
      const base = sessions * 120; // $120 per session as baseline
      if(sessionsPerWeek>=1.5) return `$${Math.round(base*1.15)} — recommended`;
      if(sessionsPerWeek>=0.9) return `$${Math.round(base)} — common choice`;
      return `$${Math.round(base*0.85)} — light support`;
    }

    function buildPlan(){
      const name = (document.getElementById('name').value || 'Client').trim();
      const email = document.getElementById('email').value.trim();
      const goal = (document.getElementById('goal').value || 'Clarify a focused change').trim();
      const duration = parseInt(document.getElementById('duration').value,10) || 8;
      const freq = document.getElementById('freq').value;
      const format = document.getElementById('format').value;
      const intensity = document.getElementById('intensity').value;
      const focus = getCheckedFocus();

      const habits = chooseHabits(focus);
      const sessionsPerWeek = parseFloat(freq);
      const sessions = Math.max(1, Math.round(duration * sessionsPerWeek));
      const checkpoints = [Math.max(1,Math.round(duration*0.25)), Math.max(2,Math.round(duration*0.5)), duration];
      const investment = estimateInvestment(duration, freq);

      const lines = [];
      lines.push(`Plan for: ${name}`);
      if(email) lines.push(`Contact: ${email}`);
      lines.push('');
      lines.push('Outcome:');
      lines.push(` - ${goal}`);
      lines.push('');
      lines.push('Structure:');
      lines.push(` - Duration: ${duration} weeks`);
      lines.push(` - Session cadence: ${sessions} sessions total (${sessionsPerWeek} per week) via ${format}`);
      lines.push(` - Intensity: ${intensity}/10`);
      if(focus.length) { lines.push(''); lines.push('Focus areas:'); focus.forEach(f=>lines.push(` - ${f}`)); }
      lines.push('');
      lines.push('Starter habits:');
      habits.forEach(h=>lines.push(` - ${h}`));
      lines.push('');
      lines.push('Checkpoints:');
      lines.push(` - Brief reviews at weeks: ${checkpoints.join(', ')}`);
      lines.push('');
      lines.push('Suggested resources:');
      lines.push(' - A single short evening routine to anchor sleep and reset');
      lines.push(' - A simple weekly planning template (shared after first session)');
      lines.push('');
      lines.push('Estimated investment:');
      lines.push(` - ${investment}`);
      lines.push('');
      lines.push('Next steps:');
      lines.push(' - Confirm this outline in a short intro call; we will refine the habit steps and checkpoints.')

      const out = lines.join('\n');
      document.getElementById('planText').textContent = out;
      return out;
    }

    document.getElementById('build').addEventListener('click', ()=>{
      buildPlan();
    });

    document.getElementById('clear').addEventListener('click', ()=>{
      document.getElementById('planner').reset();
      document.getElementById('planText').textContent = 'Your plan will appear here.';
    });

    // Copy to clipboard
    document.getElementById('copyBtn').addEventListener('click', async ()=>{
      const text = document.getElementById('planText').textContent;
      try{
        await navigator.clipboard.writeText(text);
        const original = document.getElementById('copyBtn').textContent;
        document.getElementById('copyBtn').textContent = 'Copied!';
        setTimeout(()=>document.getElementById('copyBtn').textContent = original,1400);
      }catch(e){
        alert('Could not copy automatically. You can select the text and copy.');
      }
    });

    // Download .txt
    document.getElementById('downloadBtn').addEventListener('click', ()=>{
      const text = document.getElementById('planText').textContent;
      const blob = new Blob([text],{type:'text/plain;charset=utf-8'});
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url; a.download = 'session-plan.txt';
      document.body.appendChild(a); a.click(); a.remove();
      URL.revokeObjectURL(url);
    });

    // Fill plan when arriving with query values (simple support)
    (function(){
      const params = new URLSearchParams(location.search);
      if(params.has('goal')) document.getElementById('goal').value = params.get('goal');
      if(params.has('duration')) document.getElementById('duration').value = params.get('duration');
    })();
  </script>
</body>
</html>"} 
